package provider

import (
	"encoding/json"
	"os"
	"sort"

	_ "embed"

	"github.com/pulumi/pulumi-terraform-bridge/v3/pkg/tfbridge"
	shim "github.com/pulumi/pulumi-terraform-bridge/v3/pkg/tfshim"
	"github.com/pulumi/pulumi/sdk/v3/go/common/util/contract"
)

//go:embed cmd/pulumi-resource-aws/runtime-bridge-metadata.json
var runtimeMetadata []byte

// aws-resource-metadata.json is generated by pulumi-tfgen-aws during schema generation.
//
// It records a small set of schema facts that ProviderFromMeta needs while wiring AWS-specific
// runtime behavior. Calling Resource.Schema here is too expensive for AWS startup, especially for
// SDKv2 resources with SchemaFunc implementations, so runtime uses this embedded file instead.
//
// The generator omits resources where all facts are false. A missing key therefore means
// "no generated facts" at runtime. If an upstream provider upgrade adds or changes name, region,
// tags, or tags_all schema facts, rerun schema generation so this file is refreshed; the parity
// tests below compare the embedded facts with live schemas to catch stale metadata.
//
//go:embed cmd/pulumi-resource-aws/aws-resource-metadata.json
var awsResourceMetadataBytes []byte

type awsResourceMetadata struct {
	HasInputName      bool `json:"hasInputName,omitempty"`
	HasUsableRegion   bool `json:"hasUsableRegion,omitempty"`
	HasTagsAndTagsAll bool `json:"hasTagsAndTagsAll,omitempty"`
}

var awsResourceMetadatas = parseAWSResourceMetadata()

func parseAWSResourceMetadata() map[string]awsResourceMetadata {
	var metadata map[string]awsResourceMetadata
	err := json.Unmarshal(awsResourceMetadataBytes, &metadata)
	contract.AssertNoErrorf(err, "invalid embedded AWS resource metadata")
	return metadata
}

type awsResourceMetadataLookup func(shim.Provider, string, shim.Resource) awsResourceMetadata

func embeddedAWSResourceMetadata(_ shim.Provider, key string, _ shim.Resource) awsResourceMetadata {
	return awsResourceMetadatas[key]
}

// schemaAWSResourceMetadata computes the same facts from live schemas. This is intentionally used
// by tfgen and tests, not by the runtime provider startup path.
func schemaAWSResourceMetadata(_ shim.Provider, _ string, res shim.Resource) awsResourceMetadata {
	if res == nil {
		return awsResourceMetadata{}
	}

	schema := res.Schema()
	var metadata awsResourceMetadata
	if name := schema.Get("name"); name != nil {
		metadata.HasInputName = name.Optional() || name.Required()
	}
	if region, ok := schema.GetOk("region"); ok {
		metadata.HasUsableRegion = region.Deprecated() == ""
	}
	if tags, ok := schema.GetOk("tags"); ok {
		_, hasTagsAll := schema.GetOk("tags_all")
		metadata.HasTagsAndTagsAll = hasTagsAll && (!tags.Computed() || tags.Optional())
	}

	return metadata
}

// writeAWSResourceMetadata writes the generated metadata in stable key order and omits all-false
// entries so absent runtime keys have the same meaning as zero-value metadata.
func writeAWSResourceMetadata(info *tfbridge.ProviderInfo, path string) error {
	metadata := map[string]awsResourceMetadata{}

	keys := make([]string, 0, info.P.ResourcesMap().Len())
	info.P.ResourcesMap().Range(func(key string, _ shim.Resource) bool {
		keys = append(keys, key)
		return true
	})
	sort.Strings(keys)

	for _, key := range keys {
		resourceMetadata := schemaAWSResourceMetadata(info.P, key, info.P.ResourcesMap().Get(key))
		if resourceMetadata != (awsResourceMetadata{}) {
			metadata[key] = resourceMetadata
		}
	}

	file, err := os.OpenFile(path, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0644)
	if err != nil {
		return err
	}
	defer func() {
		contract.AssertNoErrorf(file.Close(), "Failed closing %s", path)
	}()

	enc := json.NewEncoder(file)
	enc.SetIndent("", "  ")
	return enc.Encode(metadata)
}

// WriteAWSResourceMetadata is a tfgen-only helper that refreshes generated schema facts used to
// avoid runtime schema inspection.
func WriteAWSResourceMetadata(info *tfbridge.ProviderInfo, path string) error {
	return writeAWSResourceMetadata(info, path)
}
